"""Generate core/protocol/proto_gen.py from the DDNet/Kinetix generated
protocol headers (parsing them is more reliable than hand-copying tables).

Usage: python tools/gen_protocol.py <generated/protocol.h> <generated/protocol.cpp> \
           <engine/shared/protocol_ex_msgs.h>
"""

from __future__ import annotations

import re
import sys
from pathlib import Path

HEADER = r"""# GENERATED by tools/gen_protocol.py from the DDNet/Kinetix generated
# protocol headers (DDNet 20.2). Do not edit by hand.
#
# Field kinds: "i" = int32, "s" = string, "u" = uuid, "x" = int array.
"""


def parse_enums(text: str) -> dict[str, int]:
    enums: dict[str, int] = {}

    def resolve(expr: str) -> int | None:
        expr = expr.strip()
        try:
            return int(expr, 0)
        except ValueError:
            pass
        # shift/mul like "1 << 16"
        m = re.fullmatch(r"(\d+)\s*<<\s*(\d+)", expr)
        if m:
            return int(m.group(1)) << int(m.group(2))
        # symbol arithmetic A +/- B (terms: enum names or int literals)
        m = re.fullmatch(r"(\w+)\s*([+-])\s*(\w+)", expr)
        if m:
            def term(tok: str) -> int | None:
                if re.fullmatch(r"\d+", tok):
                    return int(tok)
                return enums.get(tok)
            a, b = term(m.group(1)), term(m.group(3))
            if a is not None and b is not None:
                return a + b if m.group(2) == "+" else a - b
        return enums.get(expr)

    for match in re.finditer(r"enum\s*\{([^}]*)\}", text):
        value = 0
        for entry in match.group(1).split(","):
            entry = entry.split("//")[0].strip()
            if not entry or entry.startswith("#"):
                continue
            if "=" in entry:
                name, rhs = (part.strip() for part in entry.split("=", 1))
                resolved = resolve(rhs)
                if resolved is None:
                    continue
                value = resolved
            else:
                name = entry
            if re.fullmatch(r"__[A-Z_]+", name):
                value += 1  # helper occupies a slot but is not emitted
                continue
            enums[name] = value
            value += 1
    return enums


def parse_structs(text: str) -> dict[str, dict]:
    structs: dict[str, dict] = {}
    for match in re.finditer(r"struct (CNet\w+)(?:\s*:\s*public (\w+))?\s*\{(.*?)\n\};", text, re.S):
        cls, parent, body = match.group(1), match.group(2), match.group(3)
        msg_id = re.search(r"ms_MsgId = (\w+)", body)
        fields: list[tuple[str, str, int]] = []
        for line in body.splitlines():
            line = line.strip()
            m = re.fullmatch(r"int (m_\w+)\[(\d+)\];", line)
            if m:
                fields.append((m.group(1), "x", int(m.group(2))))
                continue
            m = re.fullmatch(r"int (m_\w+);", line)
            if m:
                fields.append((m.group(1), "i", 1))
                continue
            m = re.fullmatch(r"(?:const )?char \*(?:const )?(m_\w+);", line)
            if m:
                fields.append((m.group(1), "s", 1))
                continue
            m = re.fullmatch(r"bool (m_\w+);", line)
            if m:
                fields.append((m.group(1), "i", 1))
                continue
            m = re.fullmatch(r"CUuid (m_\w+);", line)
            if m:
                fields.append((m.group(1), "u", 1))
                continue
        structs[cls] = {
            "msg_id": msg_id.group(1) if msg_id else None,
            "parent": parent,
            "fields": fields,
        }
    return structs


def resolve_fields(structs: dict[str, dict], cls: str) -> list[tuple[str, str, int]]:
    info = structs[cls]
    fields = list(info["fields"])
    if info["parent"] and info["parent"] in structs:
        fields = resolve_fields(structs, info["parent"]) + fields
    return fields


def main() -> None:
    header_path = Path(sys.argv[1])
    cpp_path = Path(sys.argv[2])
    ex_msgs_path = Path(sys.argv[3])
    text = header_path.read_text(encoding="utf-8")
    ex_text = ex_msgs_path.read_text(encoding="utf-8")

    # the generated header references ids from the teehistorian include chain
    # (OFFSET_UUID -> 22 engine uuids -> teehistorian chunks -> OFFSET_GAME_UUID);
    # synthesize that chain so enum values resolve
    if len(sys.argv) < 5:
        raise SystemExit("usage: gen_protocol.py <protocol.h> <protocol.cpp> <protocol_ex_msgs.h> <teehistorian_ex_chunks.h>")
    th_chunks = Path(sys.argv[4])
    n_ex = len(re.findall(r"UUID\(\w+", ex_text))
    n_th = len(re.findall(r"UUID\(\w+", th_chunks.read_text(encoding="utf-8"))) if th_chunks.exists() else 0
    prelude = f"enum {{ OFFSET_UUID = 1 << {16}, OFFSET_TEEHISTORIAN_UUID = OFFSET_UUID + {n_ex}, OFFSET_GAME_UUID = OFFSET_TEEHISTORIAN_UUID + {n_th} }};\n"
    text = prelude + text

    enums = parse_enums(text)
    structs = parse_structs(text)

    # uuid registries: symbol -> wire name (the uuid is derived from the name)
    game_uuids = re.findall(r'RegisterName\((\w+),\s*"([^"]+)"\)', cpp_path.read_text(encoding="utf-8"))
    ex_uuids = re.findall(r'UUID\((\w+),\s*"([^"]+)"\)', ex_text)

    lines = [HEADER]

    lines.append("# net object types with a static size (0.6): id -> symbol")
    lines.append("NETOBJ_TYPES = {")
    seen: set[int] = set()
    for name, value in sorted(enums.items(), key=lambda kv: kv[1]):
        if (
            (name.startswith("NETOBJTYPE_") or name.startswith("NETEVENTTYPE_"))
            and value < 0x4000
            and value not in seen
        ):
            seen.add(value)
            lines.append(f"    {value}: {name!r},")
    lines.append("}\n")

    lines.append("# uuid-addressed objects/messages: symbol -> wire name")
    lines.append("GAME_UUIDS = {")
    for symbol, name in game_uuids:
        lines.append(f"    {symbol!r}: {name!r},")
    lines.append("}\n")

    lines.append("# engine EX messages: symbol -> wire name")
    lines.append("EX_UUIDS = {")
    for symbol, name in ex_uuids:
        lines.append(f"    {symbol!r}: {name!r},")
    lines.append("}\n")

    lines.append("# struct symbol -> (size_bytes, [(name, kind, count)]), objects only")
    lines.append("OBJECTS = {")
    for cls in sorted(structs):
        if not cls.startswith(("CNetObj_", "CNetEvent_")):
            continue
        fields = resolve_fields(structs, cls)
        size = sum(4 * count for _, kind, count in fields if kind in "ix")
        lines.append(f"    {cls!r}: ({size}, {fields!r}),")
    lines.append("}\n")

    lines.append("# message structs: struct symbol -> [(name, kind, count)]")
    lines.append("MESSAGES = {")
    for cls in sorted(structs):
        if not cls.startswith("CNetMsg_"):
            continue
        lines.append(f"    {cls!r}: {resolve_fields(structs, cls)!r},")
    lines.append("}\n")

    lines.append("# struct symbol -> wire id symbol")
    lines.append("MSG_IDS = {")
    for cls, info in sorted(structs.items()):
        if info["msg_id"]:
            lines.append(f"    {cls!r}: {info['msg_id']!r},")
    lines.append("}\n")

    lines.append("# wire id numbers: symbol -> int (NETMSGTYPE_* game messages)")
    lines.append("NETMSG_IDS = {")
    for name, value in sorted(enums.items(), key=lambda kv: kv[1]):
        if name.startswith("NETMSGTYPE_") and value < 0x4000:
            lines.append(f"    {name!r}: {value},")
    lines.append("}\n")

    lines.append("# static snapshot item sizes: wire type symbol -> bytes (0.6 objects)")
    lines.append("OBJ_SIZES = {")
    for cls, info in sorted(structs.items()):
        if not cls.startswith(("CNetObj_", "CNetEvent_")) or not info["msg_id"]:
            continue
        if info["msg_id"] in enums and enums[info["msg_id"]] < 0x4000:
            fields = resolve_fields(structs, cls)
            size = sum(4 * count for _, kind, count in fields if kind in "ix")
            lines.append(f"    {info['msg_id']!r}: {size},")
    lines.append("}\n")

    out = Path(__file__).resolve().parents[1] / "ddnet_protocol" / "proto_gen.py"
    out.write_text("\n".join(lines) + "\n", encoding="utf-8")
    print(f"written {out} ({len(structs)} structs, {len(game_uuids)} game uuids, {len(ex_uuids)} ex uuids)")


if __name__ == "__main__":
    main()
